function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory {
  constructor(capacity, weightLimit) {
    this.capacity = capacity;
    this.weightLimit = weightLimit;
    this.slots = {};
    this.equipment = {};
    this.totalWeight = 0;
  }

  addItem(item) {
    if (Object.keys(this.slots).length >= this.capacity) return false;
    if (this.totalWeight + item.weight > this.weightLimit) return false;
    this.slots[item.id] = item;
    this.totalWeight += item.weight;
    return true;
  }

  removeItem(id) {
    const item = this.slots[id];
    if (!item) return false;
    delete this.slots[id];
    this.totalWeight -= item.weight;
    return true;
  }

  equip(id) {
    const item = this.slots[id];
    if (!item || !item.type) return false;
    if (this.equipment[item.type]) this.unequip(this.equipment[item.type].id);
    this.equipment[item.type] = item;
    return true;
  }

  unequip(id) {
    const item = this.equipment[id];
    if (!item) return false;
    delete this.equipment[id];
    return true;
  }

  getStatModifier(stat) {
    let total = 0;
    for (const item of Object.values(this.equipment)) {
      if (item.modifiers && item.modifiers[stat]) total += item.modifiers[stat];
    }
    return total;
  }
}

// Self-checking demo
const inv = new Inventory(10, 50);
assert(inv.addItem({ id: 'sword', type: 'weapon', weight: 5, modifiers: { attack: 3 } }) === true, 'adds legal item');
assert(inv.addItem({ id: 'shield', type: 'armor', weight: 10, modifiers: { defense: 2 } }) === true, 'adds another legal item');
assert(inv.addItem({ id: 'heavy', weight: 50 }) === false, 'refuses overweight item');
assert(inv.equip('sword') === true, 'equips weapon');
assert(inv.getStatModifier('attack') === 3, 'applies attack modifier');
assert(inv.unequip('sword') === true, 'unequips weapon');
assert(inv.getStatModifier('attack') === 0, 'removes attack modifier');
console.log('gen inventory modern/equipment OK');
