function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Combatant {
  constructor(name, hp, attack, defense, speed) {
    this.name = name; this.hp = hp; this.attack = attack; this.defense = defense; this.speed = speed;
    this.status = null; // 'poisoned' | 'stunned'
  }
  takeDamage(dmg) { this.hp = Math.max(0, this.hp - dmg); }
  applyStatus(effect) { this.status = effect; }
}

class CombatSystem {
  constructor(a, b) { this.a = a; this.b = b; this.log = []; }
  initiativeOrder() {
    const diff = this.a.speed - this.b.speed;
    return diff > 0 ? [this.a, this.b] : diff < 0 ? [this.b, this.a] : [this.a, this.b];
  }
  attack(attacker, defender) {
    if (attacker.status === 'stunned') { attacker.status = null; this.log.push(`${attacker.name} is stunned — no attack!`); return; }
    const rawDmg = attacker.attack - defender.defense;
    const dmg = rawDmg > 0 ? rawDmg : 0;
    defender.takeDamage(dmg);
    this.log.push(`${attacker.name} attacks ${defender.name} for ${dmg} damage`);
    if (attacker.status === 'poisoned') defender.takeDamage(3);
  }
  round() {
    const [a, b] = this.initiativeOrder();
    this.attack(a, b);
    this.attack(b, a);
  }
  report() { return this.log.join('\n'); }
}

// --- self-checking demo ---
const hero = new Combatant('Hero', 100, 12, 5, 70);
const foe  = new Combatant('Foe',  80,  9, 4, 60);
hero.applyStatus('poisoned');
foe.applyStatus('stunned');

const sim = new CombatSystem(hero, foe);
sim.round(); // hero goes first, foe is stunned — hero hits, foe takes poison damage
assert(hero.hp === 100 && foe.hp === 68, 'hero deals damage, foe takes poison');
assert(sim.log[0] === 'Hero attacks Foe for 7 damage', 'damage report logged');

for (let i = 0; i < 3; i++) sim.round(); // foe regains, fights back
assert(foe.hp < 68, 'foe took damage from hero\'s attacks');
assert(hero.hp < 100, 'hero took damage from foe\'s attacks');

while (hero.hp > 0 && foe.hp > 0) sim.round();
const winner = hero.hp > 0 ? 'Hero' : 'Foe';
console.log(sim.report());
console.log(winner + ' wins!');
