function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory {
  constructor(init = {}) { this.items = init; }
  add(id, n) { this.items[id] = (this.items[id] || 0) + n; }
  take(id, n) {
    const h = this.items[id] || 0;
    if (h < n) return false;
    this.items[id] = h - n;
    return true;
  }
  has(id, n) { return (this.items[id] || 0) >= n; }
}

class Crafting {
  constructor(inv) { this.inv = inv; this.made = {}; }
  canMake(recipe) { return recipe.cost.every(([id, n]) => this.inv.has(id, n)); }
  make(recipe) {
    if (!this.canMake(recipe)) return false;
    for (const [id, n] of recipe.cost) this.inv.take(id, n);
    this.inv.add(recipe.out, recipe.qty);
    this.made[recipe.out] = (this.made[recipe.out] || 0) + recipe.qty;
    return true;
  }
}

const inv = new Inventory({ wool: 10, stone: 5 });
const craft = new Crafting(inv);

const recipes = [
  { cost: [['wool', 2], ['stone', 1]], out: 'blanket', qty: 1 },
  { cost: [['blanket', 1], ['stone', 2]], out: 'rug', qty: 1 },
];

assert(craft.make(recipes[0]), 'the first recipe is craftable');
assert(!craft.make(recipes[0]), 'it consumes inputs so the next one is blocked');
inv.add('stone', 2);
assert(craft.make(recipes[1]), 'the second unlocks once its input is ready');
assert(inv.items.wool === 6 && inv.items.stone === 0 && inv.items.blanket === 1 && inv.items.rug === 1,
  'inputs were consumed and outputs produced exactly as promised');
console.log('gen crafting farm/basic OK');
