function heuristic(a, b) {
  return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
}

function aStar(grid, startNode, endNode) {
  const openSet = [startNode];
  const cameFrom = {};
  const gScore = {};
  const fScore = {};

  // Initialize scores
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[i].length; j++) {
      gScore[grid[i][j]] = Infinity;
      fScore[grid[i][j]] = Infinity;
    }
  }

  gScore[startNode] = 0;
  fScore[startNode] = heuristic(startNode, endNode);

  while (openSet.length > 0) {
    let current = openSet[0];
    for (let i = 1; i < openSet.length; i++) {
      if (fScore[openSet[i]] < fScore[current]) {
        current = openSet[i];
      }
    }

    if (current === endNode) {
      return reconstructPath(cameFrom, current);
    }

    openSet.splice(openSet.indexOf(current), 1);

    const neighbors = getNeighbors(grid, current);
    for (const neighbor of neighbors) {
      const tentativeGScore = gScore[current] + 1;

      if (tentativeGScore < gScore[neighbor]) {
        cameFrom[neighbor] = current;
        gScore[neighbor] = tentativeGScore;
        fScore[neighbor] = tentativeGScore + heuristic(neighbor, endNode);

        if (!openSet.includes(neighbor)) {
          openSet.push(neighbor);
        }
      }
    }
  }

  return null;
}

function reconstructPath(cameFrom, current) {
  const totalPath = [current];
  while (cameFrom[current]) {
    current = cameFrom[current];
    totalPath.unshift(current);
  }
  return totalPath;
}

function getNeighbors(grid, node) {
  const directions = [
    { x: -1, y: 0 }, // left
    { x: 1, y: 0 },  // right
    { x: 0, y: -1 }, // up
    { x: 0, y: 1 }   // down
  ];
  const neighbors = [];

  for (const direction of directions) {
    const newX = node.x + direction.x;
    const newY = node.y + direction.y;

    if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[0].length && !grid[newX][newY].isWall) {
      neighbors.push(grid[newX][newY]);
    }
  }

  return neighbors;
}

// Self-checking demo
function assert(cond, msg) {
  if (!cond) throw new Error('FAIL: ' + msg);
}

const grid = Array.from({ length: 5 }, (_, i) =>
  Array.from({ length: 5 }, (_, j) => ({ x: i, y: j, isWall: false }))
);

// Block some cells to act as obstacles
grid[2][1].isWall = true;
grid[2][2].isWall = true;
grid[2][3].isWall = true;

const startNode = grid[0][0];
const endNode = grid[4][4];

const path = aStar(grid, startNode, endNode);
assert(path !== null, 'aStar finds a path');
assert(path[0] === startNode, 'the path starts at the start node');
assert(path[path.length - 1] === endNode, 'the path ends at the end node');

console.log('A* pathfinding on a grid with obstacles OK');
