class Quest {
  constructor(id, steps, reward) {
    this.id = id; this.steps = steps; this.reward = reward;
    this.progress = 0; this.done = false;
  }
  advance(n=1) {
    this.progress = Math.min(this.progress + n, this.steps);
    if (this.progress >= this.steps && !this.done) {
      this.done = true; return this.reward;
    }
    return null;
  }
}
class QuestLog {
  constructor() { this.quests = {}; }
  add(q) { this.quests[q.id] = q; }
  advance(id, n=1) { const q=this.quests[id]; if (!q) return null; return q.advance(n); }
  get(id) { return this.quests[id]; }
}
const log = new QuestLog();
const q = new Quest('herb', 5, 'potion');
log.add(q);

assert(q.progress === 0, 'starts at zero');
let r = log.advance('herb', 2);
assert(r == null, 'no reward before completion');
assert(q.progress === 2, 'progress recorded');

r = log.advance('herb', 100);
assert(r === 'potion' && q.done, 'reward fires and quest is done on completion');
assert(log.advance('herb', 100) == null, 'a completed quest ignores further advances');
console.log('gen quest farm/multi OK');
