class Shop {
  constructor(base){this.base=base;this.stock=100;this.cache=new Map();}
  get(id){if(!this.cache.has(id)){const p=Math.max(1,this.base+Math.round(this.stock/5));this.cache.set(id,p);}return this.cache.get(id);}
  buy(id,n){const p=this.get(id);if(this.stock<n)return false;this.stock-=n;return n*p;}
  sell(id,n){const p=this.get(id);this.stock+=n;return n*p;}
}
class Inventory { constructor(){this.goods=new Map();} add(id,q){this.goods.set(id,(this.goods.get(id)||0)+q);} count(id){return this.goods.get(id)||0;} }
class Market {
  constructor(shop){this.shop=shop;this.inv=new Inventory();}
  buy(id,n){const cost=this.shop.buy(id,n);if(cost===false)return false;this.inv.add(id,n);return cost;}
  sell(id,n){const have=this.inv.count(id);if(have<n)return false;this.inv.add(id,-n);return this.shop.sell(id,n);}
}
const shop=new Shop(10), market=new Market(shop);
let paid=market.buy('ore',3);
assert(paid===30, 'buying 3 ore costs exactly 30 gold');
assert(shop.stock===97, 'the shop stock goes down by the amount bought');
assert(market.inv.count('ore')===3, 'the inventory received what was bought');
paid=market.sell('ore',2);
assert(paid===20, 'selling 2 ore earns exactly 20 gold');
assert(shop.stock===99, 'the shop restocked the 2 items sold');
assert(market.inv.count('ore')===1, 'the inventory reflects what remains');
console.log('gen economy farm/supply OK');
