function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class StatusEffects {
  constructor() { this.active = new Map(); }
  apply(name, duration, onExpiry) {
    const existing = this.active.get(name);
    if (existing) { existing.duration = Math.max(existing.duration, duration); return; }
    this.active.set(name, { duration, onExpiry });
  }
  tick(dt) {
    for (const [name, s] of this.active) {
      s.duration -= dt;
      if (s.duration <= 0) { this.active.delete(name); if (s.onExpiry) s.onExpiry(name); }
    }
  }
  has(name) { return this.active.has(name); }
  remaining(name) { const s = this.active.get(name); return s ? s.duration : 0; }
}

// Self-checking demo
const effects = new StatusEffects();
let expired = false;
effects.apply('poison', 150, () => expired = true);
assert(effects.has('poison'), 'the effect is active immediately');
assert(effects.remaining('poison') === 150, 'it has the correct duration');
effects.tick(50);
assert(effects.remaining('poison') === 100, 'duration ticks down');
effects.apply('poison', 200);
assert(effects.remaining('poison') === 200, 'stacking extends the duration');
effects.tick(200);
assert(effects.has('poison'), 'it stays active until the duration runs out');
effects.tick(10000);
assert(expired, 'the expiry callback was invoked');
assert(!effects.has('poison'), 'the effect has been cleaned up');
console.log('gen status OK');
