function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class SpatialHashGrid {
  constructor(cellSize) {
    this.cellSize = cellSize;
    this.grid = new Map();
  }

  _key(x, y) { return x + ',' + y; }

  insert(entity) {
    const { x, y, w, h } = entity;
    const minX = Math.floor(x / this.cellSize);
    const minY = Math.floor(y / this.cellSize);
    const maxX = Math.floor((x + w) / this.cellSize);
    const maxY = Math.floor((y + h) / this.cellSize);
    for (let cy = minY; cy <= maxY; cy++) {
      for (let cx = minX; cx <= maxX; cx++) {
        const key = this._key(cx, cy);
        let bucket = this.grid.get(key);
        if (!bucket) { bucket = []; this.grid.set(key, bucket); }
        bucket.push(entity);
      }
    }
  }

  queryRegion(x, y, w, h) {
    const results = [];
    const minX = Math.floor(x / this.cellSize);
    const minY = Math.floor(y / this.cellSize);
    const maxX = Math.floor((x + w) / this.cellSize);
    const maxY = Math.floor((y + h) / this.cellSize);
    for (let cy = minY; cy <= maxY; cy++) {
      for (let cx = minX; cx <= maxX; cx++) {
        const key = this._key(cx, cy);
        const bucket = this.grid.get(key);
        if (bucket) results.push(...bucket);
      }
    }
    return results;
  }

  clear() { this.grid.clear(); }
}

// --- self-checking demo ---
const grid = new SpatialHashGrid(32);
const a = { x: 10, y: 10, w: 16, h: 16 };
const b = { x: 45, y: 10, w: 16, h: 16 };
grid.insert(a); grid.insert(b);

const nearA = grid.queryRegion(0, 0, 100, 100);
assert(nearA.length === 2 && nearA.includes(a) && nearA.includes(b), 'both entities are found near the origin');

const farAway = grid.queryRegion(200, 200, 100, 100);
assert(farAway.length === 0, 'no entities are found in an empty region');

grid.clear();
const emptyAgain = grid.queryRegion(0, 0, 100, 100);
assert(emptyAgain.length === 0, 'the grid is empty after a clear');
console.log('gen collision spatial OK');
