class EventBus {
  constructor() { this._subs = new Map(); }
  on(type, cb) { this._subs.set(type, (this._subs.get(type) || []).concat(cb)); return () => this.off(type, cb); }
  once(type, cb) { const unsub = this.on(type, (...args) => { cb(...args); unsub(); }); }
  off(type, cb) { const a = this._subs.get(type) || []; this._subs.set(type, a.filter(c => c !== cb)); }
  emit(type, ...args) {
    const a = this._subs.get(type) || [];
    for (const cb of a.slice()) cb(...args);
    // Handlers can safely unsubscribe during emit — the slice above keeps the iteration stable.
    return a.length;
  }
}
const eb = new EventBus();
let seen = 0;
const sub = eb.on('foo', () => seen++);
eb.emit('foo'); eb.emit('foo');
assert(seen === 2, 'the listener fires once per emit');
sub();
eb.emit('foo');
assert(seen === 2, 'the listener stops after unsubscribe');
eb.once('one', () => seen++);
eb.emit('one'); assert(seen === 3, 'once fires exactly once');
eb.emit('one'); assert(seen === 3, 'once does not fire again');
console.log('gen-event-bus modern/subtract OK');
