class SeededRNG {
  constructor(seed){this.seed=seed;}
  next(){let s=this.seed;let x=s*16807%2147483647;this.seed=x;return x/(2**31-1);}
}
class WeightedLootTable {
  constructor(weights){this.weights=weights;this.total=weights.reduce((a,w)=>a+w,0);}
  roll(rng){let r=rng.next()*this.total;let acc=0;for(let i=0;i<this.weights.length;i++){acc+=this.weights[i];if(r<acc)return i;}return this.weights.length-1;}
}
const weights=[1,2,3,4,5];
const rng=new SeededRNG(1);
const table=new WeightedLootTable(weights);
const runs=[rng.seed,rng.seed,rng.seed].map(()=>table.roll(rng));
assert(runs[0]===runs[1]&&runs[1]===runs[2], 'reproducible for same seed');
console.log('gen weighted/independent OK');
