class AbilityCooldown {
  constructor(charges, refillSec) {
    this.charges = charges; this.maxCharges = charges;
    this.refillSec = refillSec; this.timeLeft = 0;
  }
  canUse() { return this.charges > 0; }
  use() { if (!this.canUse()) return false; this.charges--; this.timeLeft = this.refillSec; return true; }
  tick(dt) {
    if (this.timeLeft <= 0) { this.charges = Math.min(this.maxCharges, this.charges + 1); this.timeLeft = 0; return; }
    this.timeLeft = Math.max(0, this.timeLeft - dt);
  }
}
const cd = new AbilityCooldown(3, 2);
assert(cd.canUse(), 'ready to use');
assert(cd.use(), 'fires on the first use');
assert(cd.use(), 'fires again');
assert(!cd.use(), 'refused when cooldown is active');
cd.tick(1);
assert(!cd.canUse(), 'still blocked before the refill completes');
cd.tick(2);
assert(cd.canUse(), 'refilled — ready to fire again');
assert(cd.use(), 'fires once more');
assert(cd.charges === 2, 'one charge left after the refill');
console.log('gen cooldown modern/charges OK');
