class TileMap {
  constructor(grid) { this.grid = grid; this.rows = grid.length; this.cols = grid[0].length; }
  get(x, y) { if (x < 0 || y < 0 || x >= this.cols || y >= this.rows) return '#'; return this.grid[y][x]; }
  set(x, y, v) { if (x >= 0 && y >= 0 && x < this.cols && y < this.rows) this.grid[y][x] = v; }
  floodFill(x, y, from, to) {
    const seen = new Set();
    const explore = (cx, cy) => {
      if (cx < 0 || cy < 0 || cx >= this.cols || cy >= this.rows) return;
      const key = cx + ',' + cy;
      if (seen.has(key)) return;
      seen.add(key);
      if (this.get(cx, cy) !== from) return;
      this.set(cx, cy, to);
      for (const [dx, dy] of [[-1,0],[1,0],[0,-1],[0,1]]) explore(cx+dx, cy+dy);
    };
    explore(x, y);
    return seen.size;
  }
  isVisible(aX, aY, bX, bY) {
    const dx = Math.sign(bX - aX), dy = Math.sign(bY - aY);
    let x = aX, y = aY;
    while (x !== bX || y !== bY) {
      if (this.get(x, y) === '#') return false;
      x += dx; y += dy;
    }
    return true;
  }
}

// --- self-checking demo ---
const map = new TileMap([
  ['#','#','#','#','#','#','#','#','#','#'],
  ['#',' ',' ',' ',' ',' ',' ',' ',' ','#'],
  ['#',' ','#','#','#','#','#','#',' ','#'],
  ['#',' ','#',' ',' ',' ',' ','#',' ','#'],
  ['#',' ','#',' ','#','#','#',' ',' ','#'],
  ['#',' ','#',' ','#',' ',' ',' ',' ','#'],
  ['#',' ','#',' ','#',' ','#','#',' ','#'],
  ['#',' ','#',' ','#',' ','#',' ',' ','#'],
  ['#',' ','#',' ','#',' ','#',' ',' ','#'],
  ['#','#','#','#','#','#','#','#','#','#'],
]);
assert(map.floodFill(1, 1, ' ', '*') === 24, 'floodFill spreads the mark');
assert(map.get(5, 5) === '*', 'the mark replaced the floor');
assert(map.isVisible(1, 1, 9, 1), 'a clear path is visible');
assert(!map.isVisible(1, 1, 3, 3), 'a wall blocks sight');
console.log('gen/tile-map OK');
