function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory {
  constructor(init = {}) { this.goods = init; }
  add(id, qty) { this.goods[id] = (this.goods[id] || 0) + qty; }
  take(id, qty) {
    if (!this.goods[id] || this.goods[id] < qty) return false;
    this.goods[id] -= qty; return true;
  }
  count(id) { return this.goods[id] || 0; }
}

class Machine {
  constructor(src, dst, recipe) { this.src=src; this.dst=dst; this.recipe=recipe; this.made=0; }
  canMake() { for (const [id,qty] of Object.entries(this.recipe.in)) if (!this.src.take(id,qty)) return false; return true; }
  make() { for (const [id,qty] of Object.entries(this.recipe.in)) this.src.take(id,qty); for (const [id,qty] of Object.entries(this.recipe.out)) this.dst.add(id,qty); this.made++; }
}

class Chain {
  constructor(machines) { this.machines = machines; }
  tick() { for (const m of this.machines) if (m.canMake()) m.make(); }
}

