}

class InsertOp {
  constructor(doc, pos, str) { this.doc = doc; this.pos = pos; this.str = str; }
  apply() { this.doc.insert(this.pos, this.str); }
  undo() { this.doc.delete(this.pos, this.str.length); }
}

class DeleteOp {
  constructor(doc, pos, len) { this.doc = doc; this.pos = pos; this.len = len; this.removed = ''; }
  apply() { this.removed = this.doc.text.slice(this.pos, this.pos+this.len); this.doc.delete(this.pos, this.len); }
  undo() { this.doc.insert(this.pos, this.removed); }
}

