class Clock {
  constructor() {
    this.time = 0; // minutes since start
    this.day = 1;
    this.phase = 'dawn';
    this._transitions = [
      { at: 6*60,   phase: 'morning' },
      { at: 12*60,  phase: 'noon' },
      { at: 18*60,  phase: 'evening' },
      { at: 24*60,  phase: 'night' },
      { at: 24*60+6, phase: 'dawn', newDay: true },
    ];
    this._scheduled = [];
    this._listeners = {};
  }
  advance(minutes) {
    this.time += minutes;
    const startOfDay = (this.day - 1) * 24 * 60;
    let nextTrans = this._transitions[0];
    for (const t of this._transitions) {
      if (startOfDay + t.at > this.time) break;
      nextTrans = t;
    }
    if (nextTrans.newDay) this.day++;
    this.phase = nextTrans.phase;
    // Fire scheduled events at this time
    const toFire = this._scheduled.filter(e => e.at === this.time);
    this._scheduled = this._scheduled.filter(e => e.at !== this.time);
    for (const e of toFire) e.cb();
    // Notify listeners of the new phase
    const l = this._listeners[this.phase];
    if (l) for (const cb of l) cb(this.phase);
  }
  schedule(at, cb) {
    this._scheduled.push({ at, cb });
  }
  on(phase, cb) {
    this._listeners[phase] = this._listeners[phase] || [];
    this._listeners[phase].push(cb);
  }
}

