function dijkstra(graph, start, end) {
  const distances = {};
  const previousNodes = {};
  const priorityQueue = new PriorityQueue();

  // Initialize distances to all nodes as infinite except for the start node
  for (const vertex in graph) {
    distances[vertex] = Infinity;
  }
  distances[start] = 0;

  // Add all vertices to the priority queue
  for (const vertex in graph) {
    priorityQueue.enqueue(vertex, distances[vertex]);
  }

  while (!priorityQueue.isEmpty()) {
    const currentNode = priorityQueue.dequeue().value;

    if (currentNode === end) {
      break; // We've reached the end node, so we can stop
    }

    const currentDistance = distances[currentNode];

    for (const neighbor in graph[currentNode]) {
      const edgeWeight = graph[currentNode][neighbor];
      const distanceToNeighbor = currentDistance + edgeWeight;

      if (distanceToNeighbor < distances[neighbor]) {
        distances[neighbor] = distanceToNeighbor;
        previousNodes[neighbor] = currentNode;
        priorityQueue.changePriority(neighbor, distanceToNeighbor);
      }
    }
  }

  // Reconstruct the shortest path
  const path = [];
  let currentNode = end;

  while (currentNode !== undefined) {
    path.unshift(currentNode);
    currentNode = previousNodes[currentNode];
  }

  return { path, distance: distances[end] };
}

class PriorityQueue {
  constructor() {
    this.items = [];
  }

  enqueue(value, priority) {
    const queueItem = { value, priority };
    let added = false;

    for (let i = 0; i < this.items.length; i++) {
      if (queueItem.priority < this.items[i].priority) {
        this.items.splice(i, 0, queueItem);
        added = true;
        break;
      }
    }

    if (!added) {
      this.items.push(queueItem);
    }
  }

  dequeue() {
    return this.items.shift();
  }

  isEmpty() {
    return this.items.length === 0;
  }

  changePriority(value, newPriority) {
    for (let i = 0; i < this.items.length; i++) {
      if (this.items[i].value === value) {
        this.items[i].priority = newPriority;
        break;
      }
    }
  }
}

// Example usage:
const graph = {
  A: { B: 1, C: 4 },
  B: { A: 1, C: 2, D: 5 },
  C: { A: 4, B: 2, D: 1 },
  D: { B: 5, C: 1 }
};

const startNode = 'A';
const endNode = 'D';

const result = dijkstra(graph, startNode, endNode);
console.log(`Shortest path from ${startNode} to ${endNode}:`, result.path);
console.log(`Total cost:`, result.distance);
