        this.input.on('pointermove', pointer =>
        {

            const dx = pointer.x - this.player.x;
            const dy = pointer.y - this.player.y;

            let angle = Math.atan2(dy, dx);

            if (angle < 0)
            {
                angle += Math.PI * 2;
            }

            this.player.rotation = angle;
        });

        this.time.addEvent({ delay: 500, loop: true, callback: () =>
        {
            const enemy = this.add.circle(-20, Phaser.Math.Between(20, 580), 12, 0x4488ff);
            enemy.rotation = Math.PI / 2;
            this.enemies.push(enemy);
        }});

        this.time.addEvent({ delay: 200, loop: true, callback: () =>
        {
            const bullet = this.add.circle(this.player.x, this.player.y, 6, 0xffcc44);
            bullet.rotation = this.player.rotation;
            this.bullets.push(bullet);
        }});
    }

    update ()
    {
        for (let i = 0; i < this.enemies.length; i++)
        {
            const enemy = this.enemies[i];

            enemy.x += Math.cos(enemy.rotation) * 2;

            if (enemy.x > 800)
            {
                enemy.destroy();
                this.enemies.splice(i--, 1);
            }
        }

        for (let i = 0; i < this.bullets.length; i++)
        {
            const bullet = this.bullets[i];

            bullet.x += Math.cos(bullet.rotation) * 7;
            bullet.y += Math.sin(bullet.rotation) * 7;

            if (bullet.x > 800 || bullet.x < 0 || bullet.y > 600 || bullet.y < 0)
            {
                bullet.destroy();
                this.bullets.splice(i--, 1);
            }
        }

        for (let i = 0; i < this.enemies.length; i++)
        {
            const enemy = this.enemies[i];

            for (let j = 0; j < this.bullets.length; j++)
            {
                const bullet = this.bullets[j];

                if (Phaser.Geom.Intersects.CircleToCircle(bullet, enemy))
                {
                    enemy.destroy();
                    bullet.destroy();

                    this.enemies.splice(i--, 1);
                    this.bullets.splice(j--, 1);
                }
            }
        }
    }
}

