}

class Board extends Phaser.GameObjects.Container
{
    constructor (scene, x, y, width, height)
    {
        super(scene, x, y);

        this.scene = scene;
        this.width = width;
        this.height = height;

        this.grid = [];

        for (let i = 0; i < this.height; i++)
        {
            this.grid[i] = [];

            for (let j = 0; j < this.width; j++)
            {
                this.grid[i][j] = new Tile(this.scene, j * 64 + 32, i * 64 + 32, Math.floor(Math.random() * 3) + 1);
                this.add(this.grid[i][j]);
            }
        }

        this.scene.input.on('gameobjectdown', event =>
        {

            if (!this.dragging && event.gameObject instanceof Tile)
            {
                this.dragging = event.gameObject;
                this.dragging.setAlpha(0.5);
            }

        });

        this.scene.input.on('gameobjectup', event =>
        {

            if (this.dragging && event.gameObject instanceof Tile)
            {
                this.dragging.setAlpha(1);

                if (event.gameObject !== this.dragging)
                {
                    this.swapTiles(this.dragging, event.gameObject);
                }

                this.dragging = null;
            }

        });
    }

    swapTiles (tileA, tileB)
    {
        const rowA = tileA.row;
        const colA = tileA.col;
        const rowB = tileB.row;
        const colB = tileB.col;

        this.grid[rowA][colA] = tileB;
        this.grid[rowB][colB] = tileA;

        tileA.setPosition(tileB.x, tileB.y);
        tileB.setPosition(tileA.x, tileA.y);

        tileA.row = rowB;
        tileA.col = colB;
        tileB.row = rowA;
        tileB.col = colA;

        this.checkBoard();
    }

    checkBoard ()
    {
        let found = false;

        for (let i = 0; i < this.height; i++)
        {
            for (let j = 0; j < this.width; j++)
            {
                if (this.grid[i][j])
                {
                    const matches = this.findMatches(i, j);

                    if (matches.length >= 3)
                    {
                        found = true;

                        for (let k = 0; k < matches.length; k++)
                        {
                            this.grid[matches[k].row][matches[k].col] = null;
                            matches[k].destroy();
                        }
                    }
                }
            }
        }

        if (found)
        {
            this.dropTiles();
        }
    }

    findMatches (row, col)
    {
        const matches = [];

        // Check horizontal matches
        let count = 1;

        for (let j = col + 1; j < this.width; j++)
        {
            if (this.grid[row][j] && this.grid[row][j].type === this.grid[row][col].type)
            {
                count++;
            }
            else
            {
                break;
            }
        }

        for (let j = col - 1; j >= 0; j--)
        {
            if (this.grid[row][j] && this.grid[row][j].type === this.grid[row][col].type)
            {
                count++;
            }
            else
            {
                break;
            }
        }

        if (count >= 3)
        {
            for (let j = col; j < this.width; j++)
            {
                if (this.grid[row][j] && this.grid[row][j].type === this.grid[row][col].type)
                {
                    matches.push(this.grid[row][j]);
                }
                else
                {
                    break;
                }
            }

            for (let j = col - 1; j >= 0; j--)
            {
                if (this.grid[row][j] && this.grid[row][j].type === this.grid[row][col].type)
                {
                    matches.push(this.grid[row][j]);
                }
                else
                {
                    break;
                }
            }
        }

        // Check vertical matches
        count = 1;

        for (let i = row + 1; i < this.height; i++)
        {
            if (this.grid[i][col] && this.grid[i][col].type === this.grid[row][col].type)
            {
                count++;
            }
            else
            {
                break;
            }
        }

        for (let i = row - 1; i >= 0; i--)
        {
            if (this.grid[i][col] && this.grid[i][col].type === this.grid[row][col].type)
            {
                count++;
            }
            else
            {
                break;
            }
        }

        if (count >= 3)
        {
            for (let i = row; i < this.height; i++)
            {
                if (this.grid[i][col] && this.grid[i][col].type === this.grid[row][col].type)
                {
                    matches.push(this.grid[i][col]);
                }
                else
                {
                    break;
                }
            }

            for (let i = row - 1; i >= 0; i--)
            {
                if (this.grid[i][col] && this.grid[i][col].type === this.grid[row][col].type)
                {
                    matches.push(this.grid[i][col]);
                }
                else
                {
                    break;
                }
            }
        }

        return matches;
    }

    dropTiles ()
    {
        for (let j = 0; j < this.width; j++)
        {
            let emptyRow = this.height - 1;

            for (let i = this.height - 1; i >= 0; i--)
            {
                if (this.grid[i][j])
                {
                    if (i < emptyRow)
                    {
                        this.grid[i][j].row = emptyRow;
                        this.grid[i][j].y = emptyRow * 64 + 32;
                        this.grid[emptyRow][j] = this.grid[i][j];
                        this.grid[i][j] = null;
                    }

                    emptyRow--;
                }
            }

            for (let i = emptyRow; i >= 0; i--)
            {
                this.grid[i][j] = new Tile(this.scene, j * 64 + 32, i * 64 + 32, Math.floor(Math.random() * 3) + 1);
                this.add(this.grid[i][j]);
            }
        }

        this.checkBoard();
    }
}

class Tile extends Phaser.GameObjects.Container
{
    constructor (scene, x, y, type)
    {
        super(scene, x, y);

        this.type = type;
        this.row = Math.floor((y - 32) / 64);
        this.col = Math.floor((x - 32) / 64);

        const color = ['#ff0000', '#00ff00', '#0000ff'][type - 1];

        const graphics = this.scene.add.graphics();
        graphics.fillStyle(color, 1);
        graphics.fillRoundedRect(-32, -32, 64, 64, 8);

        this.add(graphics);
    }
}

