class Example extends Phaser.Scene
{
    constructor ()
    {
        super();
    }

    create ()
    {
        this.grid = new Phaser.Structs.Grid(10, 10, 640, 480);

        this.snake = [
            { x: 5, y: 5 },
            { x: 4, y: 5 },
            { x: 3, y: 5 }
        ];

        this.direction = Phaser.Math.Vector2.RIGHT;
        this.grow = false;

        this.pellet = this.grid.getRandomPosition();

        this.graphics = this.add.graphics();

        this.events.on('update', this.update, this);
    }

    update ()
    {
        this.graphics.clear();

        //  Draw the grid
        this.grid.forEach((x, y) =>
        {

            if (this.grid.contains(x, y))
            {
                this.graphics.lineStyle(1, 0xffffff, 1);
            }
            else
            {
                this.graphics.lineStyle(1, 0x000000, 1);
            }

            this.graphics.strokeRect(x, y, this.grid.cellWidth, this.grid.cellHeight);
        });

        //  Draw the snake
        this.graphics.fillStyle(0xff0000, 1);

        for (let i = 0; i < this.snake.length; i++)
        {
            const cell = this.grid.getCell(this.snake[i].x, this.snake[i].y);

            this.graphics.fillRect(cell.x, cell.y, this.grid.cellWidth, this.grid.cellHeight);
        }

        //  Draw the pellet
        const cell = this.grid.getCell(this.pellet.x, this.pellet.y);

        this.graphics.fillStyle(0xffff00, 1);
        this.graphics.fillRect(cell.x, cell.y, this.grid.cellWidth, this.grid.cellHeight);

        //  Move the snake
        const head = this.snake[0];
        const newHead = { x: head.x + this.direction.x, y: head.y + this.direction.y };

        if (!this.grid.contains(newHead.x, newHead.y))
        {
            this.restart();
            return;
        }

        if (this.grow)
        {
            this.grow = false;
        }
        else
        {
            this.snake.pop();
        }

        if (newHead.x === this.pellet.x && newHead.y === this.pellet.y)
        {
            this.grow = true;
            this.pellet = this.grid.getRandomPosition();
        }

        this.snake.unshift(newHead);

        //  Check for collisions with self
        for (let i = 1; i < this.snake.length; i++)
        {
            if (this.snake[i].x === newHead.x && this.snake[i].y === newHead.y)
            {
                this.restart();
                return;
            }
        }
    }

    restart ()
    {
        this.snake = [
            { x: 5, y: 5 },
            { x: 4, y: 5 },
            { x: 3, y: 5 }
        ];

        this.direction = Phaser.Math.Vector2.RIGHT;
        this.grow = false;

        this.pellet = this.grid.getRandomPosition();
    }

    keydown (event)
    {
        switch (event.key)
        {
            case 'ArrowUp':
                if (this.direction.y !== 1)
                {
                    this.direction.copy(Phaser.Math.Vector2.UP);
                }
                break;

            case 'ArrowDown':
                if (this.direction.y !== -1)
                {
                    this.direction.copy(Phaser.Math.Vector2.DOWN);
                }
                break;

            case 'ArrowLeft':
                if (this.direction.x !== 1)
                {
                    this.direction.copy(Phaser.Math.Vector2.LEFT);
                }
                break;

            case 'ArrowRight':
                if (this.direction.x !== -1)
                {
                    this.direction.copy(Phaser.Math.Vector2.RIGHT);
                }
                break;
        }
    }
}

