class Example extends Phaser.Scene
{
    graphics;
    enemies;
    towers;
    enemySpeed = 1.5;
    towerRange = 100;
    towerDamage = 10;
    enemyHealth = 20;
    enemyCount = 10;
    spawnInterval = 2000;

    create ()
    {
        this.graphics = this.add.graphics();

        this.enemies = [];
        this.towers = [];

        this.input.on('pointerdown', event =>
        {

            const x = event.x;
            const y = event.y;

            this.placeTower(x, y);

        });

        this.time.addEvent({ delay: this.spawnInterval, loop: true, callback: () =>
        {

            this.spawnEnemy();

        } });
    }

    update ()
    {
        this.graphics.clear();
        this.graphics.lineStyle(2, 0xff0000);
        this.graphics.strokeRect(0, 0, 800, 600);

        for (let i = 0; i < this.enemies.length; i++)
        {
            const enemy = this.enemies[i];

            enemy.x += this.enemySpeed;

            if (enemy.x > 800)
            {
                this.enemies.splice(i, 1);
                i--;
            }
            else
            {
                this.graphics.fillStyle(0xff0000);
                this.graphics.fillCircle(enemy.x, enemy.y, 10);
            }
        }

        for (let i = 0; i < this.towers.length; i++)
        {
            const tower = this.towers[i];

            this.graphics.fillStyle(0x00ff00);
            this.graphics.fillCircle(tower.x, tower.y, 10);

            let target = null;

            for (let j = 0; j < this.enemies.length; j++)
            {
                const enemy = this.enemies[j];

                const distance = Phaser.Math.Distance.Between(tower.x, tower.y, enemy.x, enemy.y);

                if (distance <= this.towerRange)
                {
                    if (!target || distance < Phaser.Math.Distance.Between(tower.x, tower.y, target.x, target.y))
                    {
                        target = enemy;
                    }
                }
            }

            if (target)
            {
                target.health -= this.towerDamage;

                if (target.health <= 0)
                {
                    this.enemies.splice(this.enemies.indexOf(target), 1);
                }
            }
        }
    }

    placeTower (x, y)
    {
        this.towers.push({ x, y });
    }

    spawnEnemy ()
    {
        this.enemies.push({ x: -10, y: 300, health: this.enemyHealth });
    }
}

