        {

            const hit = this.shapes.find(shape => shape.contains(pointer.x, pointer.y));

            if (hit)
            {
                this.input.setDraggable(hit);
            }

        });

        this.input.on('drag', (pointer, gameObject, dragX, dragY) =>
        {

            gameObject.x = dragX;
            gameObject.y = dragY;

            this.redraw();

        });

        this.input.on('dragend', (pointer, gameObject) =>
        {

            gameObject.x = Math.round(gameObject.x / 128) * 128;
            gameObject.y = Math.round(gameObject.y / 128) * 128;

            this.redraw();

        });

        this.redraw();
    }

    redraw ()
    {
        this.graphics.clear();

        this.graphics.lineStyle(2, 0x00ff00);

        this.shapes.forEach(shape =>
        {

            this.graphics.strokeRectShape(shape);

        });

        this.graphics.lineStyle(2, 0xffff00);

        this.graphics.strokeRectShape(this.grid);
