extends SceneTree

var items := {}

func add_item(id: String, qty: int) -> bool:
	if get_weight() + qty > WEIGHT_CAP:
		return false
	items[id] = qty
	return true

func remove_item(id: String, qty: int) -> bool:
	if not items.has(id) or items[id] < qty:
		return false
	items[id] -= qty
	if items[id] <= 0:
		items.erase(id)
	return true

func get_weight() -> int:
	var total := 0
	for _, v in items.values():
		total += v
	return total

var WEIGHT_CAP := 10

func _init():
	assert(add_item("scroll", 2), "adding a legal weight should succeed")
	assert(not add_item("scroll", 100), "adding over the cap is refused")
	assert(remove_item("scroll", 2), "removing a present item succeeds")
	assert(not remove_item("scroll", 1), "removing an absent item fails")
	print("get_weight(): ", get_weight())
	quit()
