extends SceneTree

var flags: Dict[str, bool] = {}

func choose(branch: int) -> bool:
	# Each branch sets a flag and requires the previous one to show its choice.
	if branch == 0:
		flags["branch_0"] = true
		return true
	if branch == 1:
		if not flags["branch_0"]:
			return false
		flags["branch_1"] = true
		return true
	if branch == 2:
		if not flags["branch_1"]:
			return false
		return true
	return false

func _init():
	assert(choose(0), "branch 0 should open")
	assert(not choose(2), "branch 2 is locked until branch 1")
	assert(choose(1), "branch 1 unlocks branch 2")
	assert(choose(2), "branch 2 now opens")
	print("reached branch 2 with world flags:", flags)
	quit()
