```gdscript
extends SceneTree

var rng := RandomStream.new(1)

func roll(weights: Array[int]) -> int:
	# Each weight is scaled by its index; the running total is the pool.
	var pool := 0
	for w in weights:
		pool += w
	# Draw a number in the range 0..pool-1. Find the interval it lands in.
	var roll := rng.randi() % pool
	var acc := 0
	for i in weights.size():
		acc += weights[i]
		if roll < acc:
			return i
	return weights.size() - 1

func _init():
	var weights := [3, 12, 5]
	var s1 := roll(weights)
	var s2 := roll(weights)
	assert(s1 == s2, "same seed gives same result")
	print("weighted roll: ", s1)
	quit()
```

