```gdscript
extends SceneTree

var ingredients := {
	"herb_1" : 2,
	"herb_2" : 3,
	"pelt"   : 1
}

var recipes := {
	"elixir" : {
		"herb_1" : 1,
		"herb_2" : 2
	}
}

func can_craft(recipe_name: String) -> bool:
	if not recipes.has(recipe_name):
		return false
	var recipe := recipes[recipe_name]
	for ingr, qty in recipe:
		if not ingredients.has(ingr) or ingredients[ingr] < qty:
			return false
	return true

func craft(recipe_name: String) -> bool:
	if not can_craft(recipe_name):
		return false
	var recipe := recipes[recipe_name]
	for ingr, qty in recipe:
		ingredients[ingr] -= qty
	return true

func _init():
	assert(can_craft("elixir"), "the recipe should be craftable with sufficient stock")
	assert(craft("elixir"), "crafting succeeds")
	assert(not can_craft("elixir"), "the recipe is now uncraftable with consumed ingredients")
	print("crafted elixir from herb_1, herb_2; remaining ingredients: ", ingredients)
	quit()
```

```gdscript
extends SceneTree

func apply_armour(base_damage: int, armour: int) -> int:
	# Armour reduces damage by its value, with a floor of 0.
	return max(0, base_damage - armour)

func apply_resistance(damage: int, resistance: float) -> int:
	# Resistance reduces damage by a percentage.
	return round(damage * (1.0 - resistance))

func damage_resolution(base_damage: int, armour: int, resistance: float) -> int:
	var d := apply_armour(base_damage, armour)
	d := apply_resistance(d, resistance)
	return d

func _init():
	assert(apply_armour(25, 10) == 15, "armour reduces damage")
	assert(apply_resistance(25, 0.1) == 23, "resistance reduces damage")
	assert(damage_resolution(25, 10, 0.1) == 23, "resistance is applied after armour")
	print("applied armour and resistance: OK")
	quit()
```

```gdscript
extends SceneTree

func compare_rarity(a: InventoryItem, b: InventoryItem) -> int:
	# Higher rarity values mean better items.
	if a.rarity < b.rarity:
		return -1
	elif a.rarity > b.rarity:
		return 1
	else:
		return a.name.builtin_compare(b.name)

func compare_name(a: InventoryItem, b: InventoryItem) -> int:
	return a.name.builtin_compare(b.name)

func sort_inventory(items: Array[InventoryItem], rarity_first: bool = true) -> Array[InventoryItem]:
	var cmp := Callable(self, "compare_name")
	if rarity_first:
		cmp = Callable(self, "compare_rarity")
	return items.sorted(cmp)

func _init():
	var items := [
		InventoryItem.new("bone", 2),
		InventoryItem.new("herb", 3),
		InventoryItem.new("potion", 5)
	]
	var got := sort_inventory(items, true)
	assert(got.size() == items.size(), "size preserved")
	assert(got[0].name.begins_with("potion"), "best item first")
	print("Rarity first: ", got.map(vale -> vale.name))
	got = sort_inventory(items, false)
	assert(got[0].name.begins_with("bone"), "name wins tie")
	print("Name first: ", got.map(vale -> vale.name))
	quit()
```

