extends SceneTree

var handlers := {}

func add_handler(name: String, cb: Callable) -> bool:
	if handlers.has(name):
		return false
	handlers[name] = cb
	return true

func dispatch(name: String, args: Array) -> Variant:
	var cb := handlers[name]
	if not cb:
		return null
	return cb.call_func_array(args)

func _init():
	assert(add_handler("update", Callable(self, "on_update")), "the handler was added")
	var result := dispatch("update", [1, 2])
	assert(result == 3, "the handler fired with the right answer")
	print("dispatched update(1, 2) got ", result)
	quit()

func on_update(a: int, b: int) -> int:
	return a + b
